def header(active):
    links=''.join(f'<a href="{href}"'+(' aria-current="page"' if href==active else '')+f'>{label}</a>' for href,label in NAV)
    return f'''<a class="skip-link" href="#main">انتقلي إلى المحتوى</a><header class="site-header"><div class="container header-inner"><a class="brand" href="index.html" aria-label="صحة — الصفحة الرئيسية"><span class="brand-mark" aria-hidden="true">✳</span><span class="brand-name">صِحّة<small>SMART HEALTHY FOOD</small></span></a><button class="menu-toggle" type="button" aria-label="فتح قائمة التنقل" aria-expanded="false">☰</button><nav class="main-nav" aria-label="التنقل الرئيسي">{links}</nav></div></header>'''

def footer():
    links=''.join(f'<li><a href="{href}">{label}</a></li>' for href,label in NAV)
    return f'''<footer class="site-footer"><div class="container"><div class="footer-grid"><div class="footer-brand"><a class="brand" href="index.html"><span class="brand-mark">✳</span><span class="brand-name">صِحّة<small>SMART HEALTHY FOOD</small></span></a><p>وجبات طازجة ومتوازنة تجعل اختيار الطعام الصحي أسهل وألذ — كل يوم.</p></div><div><h3>روابط الموقع</h3><ul class="footer-links">{links}</ul></div><div><h3>تواصلي معنا</h3><p class="footer-contact">الرياض، المملكة العربية السعودية<br>السبت – الخميس، ٨ ص إلى ١٠ م<br>hello@sehatfood.example<br>+966 55 123 4567</p></div></div><div class="footer-bottom"><span>© <span id="current-year">2026</span> صِحّة — جميع الحقوق محفوظة.</span><span>طازج، متوازن، ومن اختيارك.</span></div></div></footer><div class="toast" id="toast" role="status" aria-live="polite"></div>'''

def shell(name,title,body,active):
    return f'''<!doctype html><html lang="ar" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="theme-color" content="#f7f6ef"><meta name="description" content="صِحّة — وجبات صحية طازجة ومتوازنة في الرياض. تصفحي قائمتنا واطلبي وجبتك المفضلة."><title>{escape(title)} | صِحّة</title><link rel="stylesheet" href="styles.css"></head><body>{header(active)}<main id="main">{body}</main>{footer()}<script src="app.js" defer></script></body></html>'''

def banner(kicker,title,desc):
    return f'<section class="page-hero"><div class="container"><div class="page-banner"><span class="eyebrow">{kicker}</span><h1>{title}</h1><p>{desc}</p></div></div></section>'

def cards(items):
    return '<div class="cards">'+''.join(f'''<article class="meal-card"><img src="{img}" alt="{escape(name)} — وجبة صحية طازجة" loading="lazy"><div class="meal-card-body"><h3>{name}</h3><p>{desc}</p><div class="card-bottom"><span class="price">{price} ر.س</span><a class="small-link" href="order.html">أضيفيها للطلب ←</a></div></div></article>''' for name,price,desc,img,_ in items)+'</div>'

