def page_calculator():
    items=[('وعاء الدجاج الأخضر',36,'وجبة رئيسية'),('راب الدجاج المشوي',28,'وجبة خفيفة'),('سموذي التوت',19,'مشروب طازج'),('كرات الطاقة',16,'إضافة جانبية')]
    rows=''.join(f'<div class="calc-row" data-calc-item data-price="{price}"><span>{name}<small>{kind} · {price} ر.س</small></span><label class="hint" for="q{i}">الكمية</label><input id="q{i}" type="number" min="0" max="20" value="0" aria-label="كمية {name}"></div>' for i,(name,price,kind) in enumerate(items,1))
    body=banner('حساب سريع','كوّني طلبك واحسبي الإجمالي','غيّري الكميات وشاهدي السعر النهائي وعدد الأصناف فورًا، ثم راجعي الإجمالي قبل متابعة الطلب.')
    body+='''<section class="section"><div class="container calculator"><div class="content-card"><h2>اختاري من القائمة</h2><p class="muted">يمكنك إدخال الكمية صفرًا أو أكثر لكل صنف.</p><div class="calc-items">'''+rows+'''</div></div><aside class="summary-card calc-total"><span class="label">مجموع طلبك</span><strong id="calc-total">0.00 ر.س</strong><span>عدد الأصناف: <b id="calc-count">0</b></span><p id="calc-output" class="calc-output">اختاري وجبتك المفضلة، وسيظهر الإجمالي هنا.</p><a class="button" href="order.html">انتقلي إلى نموذج الطلب ←</a></aside></div><div class="container" style="margin-top:22px"><div class="mini-note">زودي الكمية أو قلليها بحسب حاجتك؛ يتحدث إجمالي السعر فور تغيير أي حقل.</div></div></section>'''
    return shell('calculator','حاسبة الطلب',body,'calculator.html')

def page_category(key,title,kicker,desc,active):
    body=banner(kicker,title,desc)
    body+='''<section class="section"><div class="container"><div class="category-banner"><div><strong>اختيار طازج كل يوم</strong><p>الأسعار بالريال السعودي؛ تفاصيل المكونات والقيم في صفحة القيم الغذائية.</p></div><a class="button secondary" href="nutrition.html">قارني القيم الغذائية</a></div>'''+cards(FOOD[key])+'''</div></section>'''
    return shell(key,title,body,active)

contents={
'index.html':page_home(),
'about.html':page_about(),
'nutrition.html':page_nutrition(),
'register.html':page_register(),
'order.html':page_order(),
'calculator.html':page_calculator(),
'bowls.html':page_category('bowls','أطباق توازن يومك','في طبق واحد','أطباق تجمع الحبوب الكاملة والخضار ومصادر بروتين متنوعة، محضرة لتكون وجبة مشبعة ولذيذة.','bowls.html'),
'wraps.html':page_category('wraps','الراب والسندويشات','لقمة خفيفة ومتكاملة','راب بحبوب كاملة وحشوات طازجة — مناسب لاستراحة العمل أو وجبة خفيفة أثناء يومك.','wraps.html'),
'smoothies.html':page_category('smoothies','مشروبات بطعم الطبيعة','رشفات منعشة','سموذي وفواكه ممزوجة بمكونات بسيطة لتنعشي يومك بنكهات متنوعة.','smoothies.html'),
'snacks.html':page_category('snacks','وجبات خفيفة بذكاء','بين الوجبات','إضافات صغيرة من الشوفان والفاكهة والبروتين — طعم طيب بحجم يناسب يومك.','snacks.html')}
for filename, content in contents.items():
    (ROOT/filename).write_text(content,encoding='utf-8')
